/**
* SPage — Main Application JS
* Vanilla JS, no external dependencies beyond Bootstrap
*/
(function () {
'use strict';
/* ═══════════════════════════════════════════════════════════════
1. SCROLL REVEAL — fade + slide khi phần tử vào viewport
═══════════════════════════════════════════════════════════════ */
function initScrollReveal() {
if (!('IntersectionObserver' in window)) return;
var items = document.querySelectorAll('[data-reveal], [data-reveal-x]');
if (!items.length) return;
var observer = new IntersectionObserver(function (entries) {
entries.forEach(function (entry) {
if (entry.isIntersecting) {
var el = entry.target;
var delay = el.getAttribute('data-reveal-delay') || 0;
setTimeout(function () {
el.classList.add('revealed');
}, Number(delay));
observer.unobserve(el);
}
});
}, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
items.forEach(function (el) { observer.observe(el); });
}
/* ═══════════════════════════════════════════════════════════════
2. COUNTER ANIMATION — đếm số lên khi in view
═══════════════════════════════════════════════════════════════ */
function animateCounter(el, from, to, suffix, duration) {
var start = null;
var isFloat = String(to).includes('.');
function step(ts) {
if (!start) start = ts;
var progress = Math.min((ts - start) / duration, 1);
// easeOutQuart
var ease = 1 - Math.pow(1 - progress, 4);
var current = from + (to - from) * ease;
el.textContent = (isFloat ? current.toFixed(1) : Math.floor(current).toLocaleString('vi-VN')) + suffix;
if (progress < 1) requestAnimationFrame(step);
}
requestAnimationFrame(step);
}
function initCounters() {
if (!('IntersectionObserver' in window)) return;
var counters = document.querySelectorAll('[data-count]');
if (!counters.length) return;
var observer = new IntersectionObserver(function (entries) {
entries.forEach(function (entry) {
if (entry.isIntersecting) {
var el = entry.target;
var target = parseFloat(el.getAttribute('data-count'));
var suffix = el.getAttribute('data-suffix') || el.getAttribute('data-count-suffix') || '';
var duration = parseInt(el.getAttribute('data-count-duration') || 1800);
animateCounter(el, 0, target, suffix, duration);
observer.unobserve(el);
}
});
}, { threshold: 0.5 });
counters.forEach(function (el) { observer.observe(el); });
}
/* ═══════════════════════════════════════════════════════════════
3. PROMO SLIDER — auto-play + touch/drag + dots
═══════════════════════════════════════════════════════════════ */
function initPromoSlider() {
var track = document.querySelector('.ac-promos__track');
var dots  = document.querySelectorAll('.ac-dot');
if (!track || !dots.length) return;
var cards     = track.querySelectorAll('.ac-promo-card');
var current   = 0;
var total     = dots.length;
var autoTimer = null;
var touchStartX = 0;
var isDragging  = false;
function goTo(idx) {
current = (idx + total) % total;
// Scroll to card
if (cards[current]) {
track.scrollTo({
left: cards[current].offsetLeft - 16,
behavior: 'smooth'
});
}
dots.forEach(function (d, i) {
d.classList.toggle('ac-dot--active', i === current);
});
}
function next() { goTo(current + 1); }
function startAuto() {
stopAuto();
autoTimer = setInterval(next, 4500);
}
function stopAuto() {
if (autoTimer) { clearInterval(autoTimer); autoTimer = null; }
}
// Dot clicks
dots.forEach(function (dot, i) {
dot.addEventListener('click', function () { goTo(i); startAuto(); });
});
// Touch support
track.addEventListener('touchstart', function (e) {
touchStartX = e.touches[0].clientX;
stopAuto();
}, { passive: true });
track.addEventListener('touchend', function (e) {
var diff = touchStartX - e.changedTouches[0].clientX;
if (Math.abs(diff) > 50) { diff > 0 ? next() : goTo(current - 1); }
startAuto();
}, { passive: true });
// Mouse drag
track.addEventListener('mousedown', function (e) {
touchStartX = e.clientX;
isDragging = true;
stopAuto();
e.preventDefault();
});
document.addEventListener('mouseup', function (e) {
if (!isDragging) return;
isDragging = false;
var diff = touchStartX - e.clientX;
if (Math.abs(diff) > 60) { diff > 0 ? next() : goTo(current - 1); }
startAuto();
});
// Pause on hover
track.addEventListener('mouseenter', stopAuto);
track.addEventListener('mouseleave', startAuto);
startAuto();
}
/* ═══════════════════════════════════════════════════════════════
4. TAB SYSTEM — happiness tabs + category tabs
═══════════════════════════════════════════════════════════════ */
function initTabs() {
// Generic tab groups
document.querySelectorAll('[data-tab-group]').forEach(function (group) {
var container = group.closest('[data-tabs]') || group.closest('section');
var btns  = group.querySelectorAll('[data-tab]');
var panels = container ? container.querySelectorAll('[data-tab-panel]') : [];
btns.forEach(function (btn) {
btn.addEventListener('click', function () {
var target = btn.getAttribute('data-tab');
// Deactivate all
btns.forEach(function (b) { b.classList.remove('active'); });
panels.forEach(function (p) {
p.classList.remove('active');
p.style.animation = '';
});
// Activate target
btn.classList.add('active');
var panel = container
? container.querySelector('[data-tab-panel="' + target + '"]')
: null;
if (panel) {
panel.classList.add('active');
panel.style.animation = 'tabFadeIn 0.35s ease';
}
});
});
});
// Category tabs (ac-cat-tab)
document.querySelectorAll('.ac-cat-tab').forEach(function (btn) {
btn.addEventListener('click', function () {
var siblings = btn.closest('.ac-cat-tabs')
? btn.closest('.ac-cat-tabs').querySelectorAll('.ac-cat-tab')
: [];
siblings.forEach(function (s) { s.classList.remove('active'); });
btn.classList.add('active');
// Could filter products here if data-cat attributes are added
});
});
}
/* ═══════════════════════════════════════════════════════════════
5. PRODUCT BROWSER — brand selector detail update
═══════════════════════════════════════════════════════════════ */
function initProductBrowser() {
// Brand items (defined inline via onclick="selectBrand()")
// This is a fallback delegate listener
var selector = document.querySelector('.ac-brand-selector');
if (!selector) return;
selector.addEventListener('click', function (e) {
var item = e.target.closest('.ac-brand-item');
if (!item) return;
// visual active
selector.querySelectorAll('.ac-brand-item').forEach(function (b) {
b.classList.remove('active');
});
item.classList.add('active');
// Animate detail
var detail = document.getElementById('productDetail');
if (detail) {
detail.style.animation = 'none';
detail.offsetHeight; // reflow
detail.style.animation = 'tabFadeIn 0.3s ease';
}
});
}
/* ═══════════════════════════════════════════════════════════════
6. HERO ENTRANCE — animate trên load
═══════════════════════════════════════════════════════════════ */
function initHeroEntrance() {
var left  = document.querySelector('.ac-hero__left');
var right = document.querySelector('.ac-hero__right');
var badge = document.querySelector('.ac-hero__badge');
if (!left) return;
// Stagger các elements hero
var delay = 0;
[badge, left.querySelector('.ac-hero__tagline'), left.querySelector('.ac-hero__sub'), left.querySelector('.ac-btn')].forEach(function (el) {
if (!el) return;
el.style.opacity = '0';
el.style.transform = 'translateY(30px)';
el.style.transition = 'opacity 0.7s ease ' + delay + 'ms, transform 0.7s cubic-bezier(0.22,1,0.36,1) ' + delay + 'ms';
delay += 120;
});
if (right) {
right.style.opacity = '0';
right.style.transform = 'translateX(40px)';
right.style.transition = 'opacity 0.8s ease 200ms, transform 0.9s cubic-bezier(0.22,1,0.36,1) 200ms';
}
// Trigger after paint
requestAnimationFrame(function () {
requestAnimationFrame(function () {
[badge, left.querySelector('.ac-hero__tagline'), left.querySelector('.ac-hero__sub'), left.querySelector('.ac-btn')].forEach(function (el) {
if (!el) return;
el.style.opacity = '1';
el.style.transform = 'translateY(0)';
});
if (right) {
right.style.opacity = '1';
right.style.transform = 'translateX(0)';
}
});
});
}
/* ═══════════════════════════════════════════════════════════════
7. STATS SECTION — about section phần tử stagger
═══════════════════════════════════════════════════════════════ */
function initStatsStagger() {
if (!('IntersectionObserver' in window)) return;
var statsSection = document.querySelector('.ac-stats-grid');
if (!statsSection) return;
var observer = new IntersectionObserver(function (entries) {
if (!entries[0].isIntersecting) return;
observer.disconnect();
statsSection.querySelectorAll('.ac-stat-big, .ac-stats-photo').forEach(function (el, i) {
el.style.opacity = '0';
el.style.transform = 'translateY(24px) scale(0.96)';
el.style.transition = 'opacity 0.6s ease ' + (i * 100) + 'ms, transform 0.6s cubic-bezier(0.22,1,0.36,1) ' + (i * 100) + 'ms';
requestAnimationFrame(function () {
requestAnimationFrame(function () {
el.style.opacity = '1';
el.style.transform = 'translateY(0) scale(1)';
});
});
});
}, { threshold: 0.2 });
observer.observe(statsSection);
}
/* ═══════════════════════════════════════════════════════════════
8. SUSTAINABILITY STATS REVEAL
═══════════════════════════════════════════════════════════════ */
function initSustainReveal() {
if (!('IntersectionObserver' in window)) return;
var sustain = document.querySelector('.ac-sustain');
if (!sustain) return;
var observer = new IntersectionObserver(function (entries) {
if (!entries[0].isIntersecting) return;
observer.disconnect();
sustain.querySelectorAll('.ac-sustain__stat').forEach(function (el, i) {
el.style.opacity = '0';
el.style.transform = 'translateX(-20px)';
el.style.transition = 'opacity 0.5s ease ' + (i * 130) + 'ms, transform 0.6s ease ' + (i * 130) + 'ms';
requestAnimationFrame(function () {
requestAnimationFrame(function () {
el.style.opacity = '1';
el.style.transform = 'translateX(0)';
});
});
});
}, { threshold: 0.25 });
observer.observe(sustain);
}
/* ═══════════════════════════════════════════════════════════════
9. NEWS SECTION STAGGER
═══════════════════════════════════════════════════════════════ */
function initNewsReveal() {
if (!('IntersectionObserver' in window)) return;
var newsGrid = document.querySelector('.ac-news-grid');
if (!newsGrid) return;
var observer = new IntersectionObserver(function (entries) {
if (!entries[0].isIntersecting) return;
observer.disconnect();
newsGrid.querySelectorAll('.ac-news-featured, .ac-news-item').forEach(function (el, i) {
el.style.opacity = '0';
el.style.transform = 'translateY(20px)';
el.style.transition = 'opacity 0.55s ease ' + (i * 90) + 'ms, transform 0.6s ease ' + (i * 90) + 'ms';
requestAnimationFrame(function () {
requestAnimationFrame(function () {
el.style.opacity = '1';
el.style.transform = 'translateY(0)';
});
});
});
}, { threshold: 0.1 });
observer.observe(newsGrid);
}
/* ═══════════════════════════════════════════════════════════════
10. PROMO CARDS STAGGER (on scroll)
═══════════════════════════════════════════════════════════════ */
function initPromoReveal() {
if (!('IntersectionObserver' in window)) return;
var promos = document.querySelector('.ac-promos');
if (!promos) return;
var observer = new IntersectionObserver(function (entries) {
if (!entries[0].isIntersecting) return;
observer.disconnect();
promos.querySelectorAll('.ac-promo-card').forEach(function (el, i) {
el.style.opacity = '0';
el.style.transform = 'translateY(30px)';
el.style.transition = 'opacity 0.6s ease ' + (i * 100) + 'ms, transform 0.65s cubic-bezier(0.22,1,0.36,1) ' + (i * 100) + 'ms';
requestAnimationFrame(function () {
requestAnimationFrame(function () {
el.style.opacity = '1';
el.style.transform = 'translateY(0)';
});
});
});
}, { threshold: 0.1 });
observer.observe(promos);
}
/* ═══════════════════════════════════════════════════════════════
11. HAPPINESS SECTION REVEAL
═══════════════════════════════════════════════════════════════ */
function initHappinessReveal() {
if (!('IntersectionObserver' in window)) return;
var section = document.querySelector('.ac-happiness');
if (!section) return;
var observer = new IntersectionObserver(function (entries) {
if (!entries[0].isIntersecting) return;
observer.disconnect();
var title = section.querySelector('.ac-section-title');
var tabs  = section.querySelector('.ac-tabs');
if (title) {
title.style.opacity = '0';
title.style.transform = 'translateY(20px)';
title.style.transition = 'opacity 0.5s ease, transform 0.5s ease';
}
if (tabs) {
tabs.style.opacity = '0';
tabs.style.transform = 'translateY(16px)';
tabs.style.transition = 'opacity 0.5s ease 150ms, transform 0.5s ease 150ms';
}
requestAnimationFrame(function () {
requestAnimationFrame(function () {
if (title) { title.style.opacity='1'; title.style.transform='translateY(0)'; }
if (tabs)  { tabs.style.opacity='1';  tabs.style.transform='translateY(0)'; }
});
});
}, { threshold: 0.2 });
observer.observe(section);
}
/* ═══════════════════════════════════════════════════════════════
12. SMOOTH HOVER RIPPLE trên ac-btn
═══════════════════════════════════════════════════════════════ */
function initRipple() {
document.querySelectorAll('.ac-btn, .ac-tab, .ac-cat-tab').forEach(function (btn) {
btn.addEventListener('click', function (e) {
var rect = btn.getBoundingClientRect();
var x = e.clientX - rect.left;
var y = e.clientY - rect.top;
var ripple = document.createElement('span');
ripple.style.cssText = [
'position:absolute',
'border-radius:50%',
'background:rgba(255,255,255,0.35)',
'width:8px',
'height:8px',
'left:' + (x - 4) + 'px',
'top:' + (y - 4) + 'px',
'transform:scale(0)',
'animation:ripple-anim 0.55s ease-out forwards',
'pointer-events:none',
].join(';');
var pos = getComputedStyle(btn).position;
if (pos === 'static') btn.style.position = 'relative';
btn.style.overflow = 'hidden';
btn.appendChild(ripple);
setTimeout(function () { ripple.remove(); }, 600);
});
});
}
/* ═══════════════════════════════════════════════════════════════
13. LAZY LOAD IMAGES (fallback)
═══════════════════════════════════════════════════════════════ */
function initLazyLoad() {
if (!('IntersectionObserver' in window)) return;
document.querySelectorAll('img[data-src]').forEach(function (img) {
var io = new IntersectionObserver(function (entries) {
if (entries[0].isIntersecting) {
img.src = img.dataset.src;
if (img.dataset.srcset) img.srcset = img.dataset.srcset;
io.disconnect();
}
});
io.observe(img);
});
}
/* ═══════════════════════════════════════════════════════════════
14. READING PROGRESS BAR
═══════════════════════════════════════════════════════════════ */
function initReadingProgress() {
var article = document.querySelector('.post-detail__content');
if (!article) return;
var bar = document.createElement('div');
bar.style.cssText = 'position:fixed;top:0;left:0;height:3px;background:var(--color-primary);z-index:9999;transition:width 80ms linear;width:0;pointer-events:none';
document.body.appendChild(bar);
window.addEventListener('scroll', function () {
var total = article.offsetTop + article.offsetHeight - window.innerHeight;
var pct = Math.min((window.scrollY / total) * 100, 100);
bar.style.width = Math.max(pct, 0) + '%';
}, { passive: true });
}
/* ═══════════════════════════════════════════════════════════════
15. GOOGLE TRANSLATE CUSTOM WIDGET
═══════════════════════════════════════════════════════════════ */
function initGoogleTranslate() {
var trigger  = document.getElementById('gt-trigger');
var dropdown = document.getElementById('gt-dropdown');
var widget   = document.getElementById('gt-widget');
if (!trigger || !dropdown) return;
var flagEl  = document.getElementById('gt-current-flag');
var labelEl = document.getElementById('gt-current-label');
var langMeta = {
'vi':    { flag: '🇻🇳', label: 'VI' },
'en':    { flag: '🇬🇧', label: 'EN' },
'zh-CN': { flag: '🇨🇳', label: 'ZH' },
'ja':    { flag: '🇯🇵', label: 'JA' },
'ko':    { flag: '🇰🇷', label: 'KO' },
'fr':    { flag: '🇫🇷', label: 'FR' },
};
function openDropdown() {
dropdown.classList.add('gt-dropdown--open');
trigger.setAttribute('aria-expanded', 'true');
}
function closeDropdown() {
dropdown.classList.remove('gt-dropdown--open');
trigger.setAttribute('aria-expanded', 'false');
}
trigger.addEventListener('click', function (e) {
e.stopPropagation();
var isOpen = dropdown.classList.contains('gt-dropdown--open');
isOpen ? closeDropdown() : openDropdown();
});
document.addEventListener('click', function (e) {
if (!widget.contains(e.target)) closeDropdown();
});
document.addEventListener('keydown', function (e) {
if (e.key === 'Escape') closeDropdown();
});
dropdown.querySelectorAll('.gt-option').forEach(function (opt) {
opt.addEventListener('click', function () {
var pair = opt.getAttribute('data-gt');
var lang = opt.getAttribute('data-lang');
if (!pair) return;
// Call Google Translate internal function
if (typeof doGTranslate === 'function') {
doGTranslate(pair);
} else {
// Fallback: trigger via cookie + reload
var toCodes = pair.split('|');
var toLang  = toCodes[1] || lang;
document.cookie = 'googtrans=/auto/' + toLang + ';path=/';
window.location.reload();
}
// Update trigger display
var meta = langMeta[lang];
if (meta && flagEl && labelEl) {
flagEl.textContent  = meta.flag;
labelEl.textContent = meta.label;
}
// Hide selected, show all others
dropdown.querySelectorAll('.gt-option').forEach(function (o) {
o.classList.toggle('gt-option--hidden', o === opt);
});
closeDropdown();
});
});
}
/* ═══════════════════════════════════════════════════════════════
16. QUALITY SECTION REVEAL
═══════════════════════════════════════════════════════════════ */
function initQualityReveal() {
if (!('IntersectionObserver' in window)) return;
var section = document.querySelector('.ac-quality');
if (!section) return;
var observer = new IntersectionObserver(function (entries) {
if (!entries[0].isIntersecting) return;
observer.disconnect();
var text  = section.querySelector('.ac-quality__text');
var media = section.querySelector('.ac-quality__media');
if (text) {
text.style.opacity = '0';
text.style.transform = 'translateX(-30px)';
text.style.transition = 'opacity 0.7s ease, transform 0.7s ease';
}
if (media) {
media.style.opacity = '0';
media.style.transform = 'translateX(30px)';
media.style.transition = 'opacity 0.7s ease 100ms, transform 0.7s ease 100ms';
}
requestAnimationFrame(function () {
requestAnimationFrame(function () {
if (text)  { text.style.opacity='1';  text.style.transform='translateX(0)'; }
if (media) { media.style.opacity='1'; media.style.transform='translateX(0)'; }
});
});
}, { threshold: 0.15 });
observer.observe(section);
}
/* ═══════════════════════════════════════════════════════════════
INIT ALL
═══════════════════════════════════════════════════════════════ */
function init() {
initHeroEntrance();
initScrollReveal();
initCounters();
initPromoSlider();
initTabs();
initProductBrowser();
initStatsStagger();
initSustainReveal();
initNewsReveal();
initPromoReveal();
initHappinessReveal();
initQualityReveal();
initRipple();
initLazyLoad();
initReadingProgress();
initGoogleTranslate();
}
if (document.readyState === 'loading') {
document.addEventListener('DOMContentLoaded', init);
} else {
init();
}
})();
